package com.unoarena.game;

import org.springframework.stereotype.Service;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

@Service
public class GameService {
    public record Room(String code,String name,String hostId,String hostName,int players,int maxPlayers,String status,boolean isPrivate,boolean computer,List<String[]> seats){}
    public record ComputerSession(Room room,UnoGame.View game){}
    private static final class RoomState {final String code,name,hostId,hostName;final int max;final boolean isPrivate,computer;final List<String[]> seats=new ArrayList<>();UnoGame game;RoomState(String code,String name,String id,String user,int max,boolean priv,boolean computer){this.code=code;this.name=name;hostId=id;hostName=user;this.max=max;isPrivate=priv;this.computer=computer;seats.add(new String[]{id,user});}Room view(){return new Room(code,name,hostId,hostName,seats.size(),max,game==null?"WAITING":"PLAYING",isPrivate,computer,seats.stream().map(seat -> new String[]{seat[0],seat[1]}).toList());}}
    private final Map<String,RoomState> rooms=new ConcurrentHashMap<>();private final Map<String,UnoGame> games=new ConcurrentHashMap<>();
    public synchronized Room create(String name,String userId,String username,int max,boolean priv){if(max<2||max>4)throw new IllegalArgumentException("PLAYER_LIMIT");String code;do{code="UNO-"+String.format("%03d",new Random().nextInt(1000));}while(rooms.containsKey(code));RoomState r=new RoomState(code,name,userId,username,max,priv,false);rooms.put(code,r);return r.view();}
    public synchronized ComputerSession createComputerGame(String userId,String username,int botCount){if(botCount<1||botCount>3)throw new IllegalArgumentException("COMPUTER_PLAYER_LIMIT");int max=botCount+1;String code;do{code="UNO-"+String.format("%03d",new Random().nextInt(1000));}while(rooms.containsKey(code));RoomState r=new RoomState(code,"UNO vs Computer",userId,username,max,true,true);for(int i=1;i<=botCount;i++)r.seats.add(new String[]{"BOT-"+UUID.randomUUID(),"Computer "+i});r.game=new UnoGame(code,r.seats);rooms.put(code,r);games.put(code,r.game);return new ComputerSession(r.view(),r.game.view(userId));}
    public List<Room> list(){return rooms.values().stream().filter(r->!r.isPrivate&&r.game==null).map(RoomState::view).toList();}
    public synchronized Room getRoom(String code){return room(code).view();}
    public synchronized Room join(String code,String userId,String username){RoomState r=rooms.get(code);if(r==null)throw new NoSuchElementException("ROOM_NOT_FOUND");if(r.game!=null||r.seats.size()>=r.max)throw new IllegalStateException("ROOM_FULL_OR_STARTED");if(r.seats.stream().noneMatch(p->p[0].equals(userId)))r.seats.add(new String[]{userId,username});return r.view();}
    public synchronized Room returnToRoom(String code,String userId){RoomState r=room(code);if(!r.hostId.equals(userId))throw new IllegalStateException("HOST_ONLY");if(r.game==null||!r.game.isFinished())throw new IllegalStateException("GAME_NOT_FINISHED");games.remove(code);r.game=null;return r.view();}
    public synchronized void end(String code,String userId){RoomState r=room(code);if(!r.hostId.equals(userId))throw new IllegalStateException("HOST_ONLY");if(r.game==null)throw new IllegalStateException("GAME_NOT_STARTED");if(!r.game.isFinished())r.game.end(userId);games.remove(code);rooms.remove(code);}
    public synchronized UnoGame.View start(String code,String userId){RoomState r=room(code);if(!r.hostId.equals(userId))throw new IllegalStateException("HOST_ONLY");if(r.game!=null)throw new IllegalStateException("GAME_ALREADY_STARTED");if(r.seats.size()<2)throw new IllegalStateException("NEED_MORE_PLAYERS");r.game=new UnoGame(code,r.seats);games.put(code,r.game);return r.game.view(userId);}
    public UnoGame.View view(String id,String userId){return game(id).view(userId);}
    public synchronized UnoGame.View play(String id,String userId,String card,UnoGame.Color color){RoomState r=room(id);return r.game.play(userId,card,color);}
    public synchronized UnoGame.View draw(String id,String userId){RoomState r=room(id);return r.game.draw(userId);}
    public synchronized UnoGame.View uno(String id,String userId){RoomState r=room(id);return r.game.uno(userId);}
    public synchronized UnoGame.View computerTurn(String id,String viewerId,String expectedBotId){RoomState r=room(id);if(!r.computer)throw new IllegalStateException("NOT_COMPUTER_GAME");UnoGame.View state=r.game.view(viewerId);if(state.status()!=UnoGame.Status.PLAYING)return state;String currentId=state.players().get(state.currentPlayer()).id();if(!currentId.equals(expectedBotId)||!currentId.startsWith("BOT-"))return state;UnoGame.View botView=r.game.view(currentId);UnoGame.PlayerView bot=botView.players().stream().filter(p->p.id().equals(currentId)).findFirst().orElseThrow();UnoGame.Card card=bot.hand().stream().filter(c->isPlayable(c,state)).findFirst().orElse(null);if(card==null)r.game.draw(currentId);else{UnoGame.Color chosen=card.color()==UnoGame.Color.WILD?computerColor(bot.hand()):null;r.game.play(currentId,card.id(),chosen);}return r.game.view(viewerId);}
    private boolean isPlayable(UnoGame.Card card,UnoGame.View state){UnoGame.Card top=state.topCard();return card.color()==UnoGame.Color.WILD||card.color()==state.currentColor()||(card.type()==top.type()&&card.type()!=UnoGame.Type.NUMBER)||(card.type()==UnoGame.Type.NUMBER&&top.type()==UnoGame.Type.NUMBER&&card.value()==top.value());}
    private UnoGame.Color computerColor(List<UnoGame.Card> hand){Map<UnoGame.Color,Integer> counts=new EnumMap<>(UnoGame.Color.class);for(UnoGame.Card card:hand)if(card.color()!=UnoGame.Color.WILD)counts.merge(card.color(),1,Integer::sum);return Arrays.stream(new UnoGame.Color[]{UnoGame.Color.RED,UnoGame.Color.BLUE,UnoGame.Color.GREEN,UnoGame.Color.YELLOW}).max(Comparator.comparingInt(color->counts.getOrDefault(color,0))).orElse(UnoGame.Color.RED);}
    public String username(String id){RoomState r=rooms.values().stream().filter(x->x.seats.stream().anyMatch(p->p[0].equals(id))).findFirst().orElseThrow(()->new NoSuchElementException("USER_NOT_IN_ROOM"));return r.seats.stream().filter(p->p[0].equals(id)).findFirst().orElseThrow()[1];}
    private RoomState room(String id){RoomState r=rooms.get(id);if(r==null)throw new NoSuchElementException("ROOM_NOT_FOUND");return r;}private UnoGame game(String id){UnoGame g=games.get(id);if(g==null)throw new NoSuchElementException("GAME_NOT_FOUND");return g;}
}
